import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<String> games = new ArrayList<>();
        games.add("CS");
        games.add("Dota");
        System.out.println(games.get(0) + ", всего: " + games.size());

        Map<String, Integer> levels = new HashMap<>();
        levels.put("Азиз", 7);
        levels.put("Тимур", 4);

        for (Map.Entry<String, Integer> e : levels.entrySet()) {
            System.out.println(e.getKey() + ": " + e.getValue());
        }

        // Современная Java: стримы вместо циклов
        int sum = games.stream().mapToInt(String::length).sum();
        System.out.println("Сумма длин: " + sum);
    }
}

