import java.util.*;

public class Main {
    static Map<String, Integer> countWords(String[] words) {
        Map<String, Integer> counts = new HashMap<>();
        for (String w : words) {
            counts.put(w, counts.getOrDefault(w, 0) + 1);   // как dict.get(w, 0) + 1
        }
        return counts;
    }

    public static void main(String[] args) {
        System.out.println(countWords(new String[]{"java", "sql", "java"}));
        // {java=2, sql=1}
    }
}

