class Unit {
    protected String name;      // protected: видно наследникам

    public Unit(String name) {
        this.name = name;
    }

    public void info() {
        System.out.println("Юнит: " + name);
    }
}

class Archer extends Unit {
    public Archer(String name) {
        super(name);            // вызов конструктора родителя - обязателен первой строкой
    }

    public void shoot() {
        System.out.println(name + " стреляет!");
    }
}

public class Main {
    public static void main(String[] args) {
        Archer a = new Archer("Леголас");
        a.info();      // унаследованный метод
        a.shoot();     // собственный метод
    }
}
